import React from 'react';
import { NavLink } from 'react-router-dom';

const Navbar = () => {
  return (
    <nav style={{ 
      backgroundColor: '#333', 
      padding: '10px 20px',
      marginBottom: '20px'
    }}>
      <ul style={{ 
        listStyle: 'none', 
        display: 'flex', 
        gap: '20px', 
        margin: 0, 
        padding: 0 
      }}>
        <li>
          <NavLink 
            to="/" 
            style={({ isActive }) => ({
              color: 'white',
              textDecoration: 'none',
              padding: '5px 10px',
              backgroundColor: isActive ? '#007bff' : 'transparent',
              borderRadius: '4px'
            })}
          >
            Home
          </NavLink>
        </li>
        <li>
          <NavLink 
            to="/about"
            style={({ isActive }) => ({
              color: 'white',
              textDecoration: 'none',
              padding: '5px 10px',
              backgroundColor: isActive ? '#007bff' : 'transparent',
              borderRadius: '4px'
            })}
          >
            About
          </NavLink>
        </li>
        <li>
          <NavLink 
            to="/contact"
            style={({ isActive }) => ({
              color: 'white',
              textDecoration: 'none',
              padding: '5px 10px',
              backgroundColor: isActive ? '#007bff' : 'transparent',
              borderRadius: '4px'
            })}
          >
            Contact
          </NavLink>
        </li>
        <li>
          <NavLink 
            to="/product/1"
            style={({ isActive }) => ({
              color: 'white',
              textDecoration: 'none',
              padding: '5px 10px',
              backgroundColor: isActive ? '#007bff' : 'transparent',
              borderRadius: '4px'
            })}
          >
            Products
          </NavLink>
        </li>
      </ul>
    </nav>
  );
};

export default Navbar;
